import java.util.*;
import java.lang.reflect.Field;

/**
 * Headless deterministic harness. Reflectively seeds the three persistent
 * Random instances (which are otherwise unseeded), then replicates
 * Simulator.populate()/simulateOneStep() WITHOUT the Swing view and
 * fingerprints the position-sensitive field state each step.
 *
 * The same harness + seeds is run against baseline vs refactored model
 * classes; the fingerprints must be identical for a behaviour-preserving
 * refactor.
 */
public class Harness {
    static final int DEPTH = 60, WIDTH = 90, STEPS = 120;
    // Mirror Simulator's creation probabilities exactly.
    static final double LION = 0.0125, CHEETAH = 0.0125, ZEBRA = 0.08, GIRAFFE = 0.08, LEMUR = 0.081;

    static final long FNV_OFFSET = -3750763034362895579L; // 0xcbf29ce484222325
    static final long FNV_PRIME  = 1099511628211L;

    static void seedStatic(Class<?> c, long s) throws Exception {
        Field f = c.getDeclaredField("rand");
        f.setAccessible(true);
        ((Random) f.get(null)).setSeed(s);
    }

    static long fnv(long h, long v) {
        for (int i = 0; i < 8; i++) {
            h ^= (v & 0xff);
            h *= FNV_PRIME;
            v >>>= 8;
        }
        return h;
    }

    public static void main(String[] args) throws Exception {
        // Seed the three persistent generators deterministically.
        seedStatic(LivingOrganism.class, 424242L);
        seedStatic(Field.class, 424242L);
        seedStatic(Weather.class, 424242L);

        Time.resetStep();

        ehField field = null; // placeholder
        Field2 unused = null;  // placeholder
        run();
    }

    // populate replication (mirrors Simulator.populate, with a fixed-seed local rand)
    static List<LivingOrganism> animals = new ArrayList<>();
    static List<LivingOrganism> plants = new ArrayList<>();
    static Field field;

    static void populate(Random rand) {
        field.clear();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                Plant plant = new Plant(true, field, location);
                plants.add(plant);

                Animal animal = null;
                if (rand.nextDouble() <= LION)            animal = new Lion(true, field, location, false, false);
                else if (rand.nextDouble() <= CHEETAH)    animal = new Cheetah(true, field, location, false, false);
                else if (rand.nextDouble() <= ZEBRA)      animal = new Zebra(true, field, location, false, false);
                else if (rand.nextDouble() <= GIRAFFE)    animal = new Giraffe(true, field, location, false, false);
                else if (rand.nextDouble() <= LEMUR)      animal = new Lemur(true, field, location, false, false);

                if (animal != null) animals.add(animal);
            }
        }
    }

    static void step() {
        Time.incrementStep();
        Weather.updateWeather();
        List<LivingOrganism> newAnimals = new ArrayList<>();
        List<LivingOrganism> newPlants = new ArrayList<>();

        for (Iterator<LivingOrganism> it = animals.iterator(); it.hasNext();) {
            Animal animal = (Animal) it.next();
            if (animal != null) {
                animal.act(newAnimals);
                if (!animal.isAlive()) it.remove();
            }
        }
        for (Iterator<LivingOrganism> it = plants.iterator(); it.hasNext();) {
            Plant plant = (Plant) it.next();
            if (plant != null) {
                plant.act(newPlants);
                if (!plant.isAlive()) it.remove();
            }
        }
        animals.addAll(newAnimals);
        plants.addAll(newPlants);
    }

    static long fingerprintField() {
        long h = FNV_OFFSET;
