        for (Iterator<LivingOrganism> it = animals.iterator(); it.hasNext();) {
            Animal animal = (Animal) it.next();
            if (animal != null) {
                animal.act(newAnimals);
                if (!animal.isAlive()) it.remove();
            }
        }
        for (Iterator<LivingOrganism> it = plants.iterator(); it.hasNext();) {
            Plant plant = (Plant) it.next();
            if (plant != null) {
                plant.act(newPlants);
                if (!plant.isAlive()) it.remove();
            }
        }
        animals.addAll(newAnimals);
        plants.addAll(newPlants);
    }

    static long fingerprintField() {
        long h = FNV_OFFSET;
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Location loc = new Location(row, col);
                Object a = field.getObjectAt(loc, Animal.class);
                Object p = field.getObjectAt(loc, Plant.class);
                long sig = 0;
                if (a != null) {
                    sig = a.getClass().getSimpleName().hashCode() & 0xffffffffL;
                    if (((Animal) a).getIsInfected()) sig ^= 0x9e3779b97f4a7c15L;
                    if (((Animal) a).getIsImmune())   sig ^= 0x517cc1b727220a95L;
                }
                if (p != null) sig ^= 0x1000000L;
                h = fnv(h, sig);
            }
        }
        return h;
    }

    static void run() {
        field = new Field(DEPTH, WIDTH);
        Random popRand = new Random(987654321L);
        populate(popRand);

        long acc = FNV_OFFSET;
        for (int s = 0; s < STEPS; s++) {
            step();
            acc = fnv(acc, fingerprintField());
        }
        System.out.println("STEPS=" + STEPS + " animals=" + animals.size() + " plants=" + plants.size());
        System.out.println("FINGERPRINT=" + acc);
    }
}

